.ds-btn {display: inline-flex; justify-content: center; align-items: center; gap: 8px; min-height: 38px; padding: 8px 17px; border: 1px solid var(--frame, #b5d3df); border-radius: 5px; color: var(--text, #173c50); background: linear-gradient(var(--chrome-top, rgb(247 253 255 / 72%)) 0%, var(--surface-soft, #eaf3f8) 48%, var(--chrome-bottom, rgb(162 208 230 / 35%)) 50%, var(--surface-soft, #eaf3f8)); box-shadow: inset 0 1px 0 rgb(255 255 255 / 65%), 0 1px 2px rgb(0 40 60 / 10%); font-size: 13px; font-weight: 600; text-decoration: none; transition: filter 140ms ease, box-shadow 140ms ease;}
.ds-btn:hover:not(:disabled) {filter: brightness(1.06); border-color: var(--focus, #006da6);}
.ds-btn:active:not(:disabled) {box-shadow: inset 0 2px 4px rgb(0 30 50 / 25%);}
.ds-btn-primary {color: var(--primary-text, #fff); border-color: var(--primary-edge, #075c8b); background: linear-gradient(var(--primary-top, #1875a4), #176c98 49%, var(--primary-bottom, #086699) 50%, #126b99); text-shadow: 0 1px 1px rgb(0 30 60 / 40%); min-width: 135px;}
.ds-btn:disabled {opacity: .6; filter: saturate(.4); box-shadow: none;}
:host {font-family: "Open Sans", "Segoe UI", sans-serif; color: var(--text, #173c50); font-size:14px; line-height:1.6;}
button,input,select {font:inherit;}
button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible {outline:3px solid var(--focus, #006da6);outline-offset:3px;}
@media (prefers-reduced-motion:reduce) {button {transition:none !important;}}

