.ds-field {display: flex; flex-direction: column; gap: 6px; min-width: 0;}
.ds-field input {width: 100%; min-height: 42px; border: 1px solid var(--frame, #b5d3df); border-top-color: var(--line, #bfd2df); border-radius: 4px; background: var(--field, #fff); color: var(--text, #173c50); padding: 9px 11px; box-shadow: inset 0 2px 4px rgb(12 54 76 / 8%);}
.ds-field input:hover {border-color: var(--muted, #355467);}
.ds-field input:focus {border-color: var(--focus, #006da6);}
.ds-field input[aria-invalid='true'] {border-color: var(--danger, #a9342b);}
