.ds-code {display: grid; grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: 'label copy' 'value copy' 'expiry copy'; gap: 4px 12px; padding: 18px; border-radius: 6px; background: var(--field, #fff); border: 1px solid var(--frame, #b5d3df); box-shadow: inset 0 2px 5px rgb(10 50 70 / 7%);}
.ds-code-label {grid-area: label; color: var(--muted, #355467); font-size: 12px;}
.ds-code-value {grid-area: value; font: 600 clamp(25px, 3vw, 34px)/1.4 'Consolas', monospace; letter-spacing: 2px; overflow-wrap: anywhere;}
.ds-code-expiry {grid-area: expiry; color: var(--muted, #355467); font-size: 12px; font-variant-numeric: tabular-nums;}
.ds-code-copy {grid-area: copy; align-self: center;}
